CREATE DATABASE IF NOT EXISTS db_keperawatan CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_keperawatan;

CREATE TABLE IF NOT EXISTS users (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(100) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role ENUM('perawat','mahasiswa','penguji') NOT NULL DEFAULT 'perawat',
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pengajuan (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    jenis_tes VARCHAR(3) NOT NULL,
    topik VARCHAR(255) DEFAULT NULL,
    tanggal_tes DATE DEFAULT NULL,
    status ENUM('Menunggu','Diterima','Ditolak') NOT NULL DEFAULT 'Menunggu',
    penguji_id INT DEFAULT NULL,
    tanggal_pengajuan TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tanggal_diterima DATETIME DEFAULT NULL,
    INDEX idx_pengajuan_user (user_id, jenis_tes),
    INDEX idx_pengajuan_penguji (penguji_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS hasil_tes (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    jenis_tes VARCHAR(3) NOT NULL,
    file_name VARCHAR(255) NOT NULL DEFAULT '',
    file_path VARCHAR(1000) NOT NULL DEFAULT '',
    status ENUM('Belum Selesai','Selesai') NOT NULL DEFAULT 'Belum Selesai',
    penguji_id INT DEFAULT NULL,
    catatan TEXT DEFAULT NULL,
    penilaian LONGTEXT DEFAULT NULL,
    tanggal_upload TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tanggal_selesai DATETIME DEFAULT NULL,
    INDEX idx_hasil_user (user_id, jenis_tes, status),
    INDEX idx_hasil_penguji (penguji_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS soal_lisan (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    jenis_tes VARCHAR(3) NOT NULL,
    soal TEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS bank_soal (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    jenis_tes VARCHAR(3) NOT NULL,
    topik VARCHAR(255) NOT NULL,
    judul VARCHAR(200) NOT NULL,
    deskripsi TEXT NOT NULL,
    pertanyaan LONGTEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY bank_soal_tahap_topik (jenis_tes, topik)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS form_ujian (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    pengajuan_id INT NOT NULL UNIQUE,
    judul VARCHAR(200) NOT NULL,
    deskripsi TEXT NOT NULL,
    pertanyaan LONGTEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS jawaban_form (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    form_id INT NOT NULL UNIQUE,
    hasil_id INT NOT NULL UNIQUE,
    jawaban LONGTEXT NOT NULL,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS banding_asesmen (
    id INT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    hasil_id INT NOT NULL UNIQUE,
    user_id INT NOT NULL,
    penguji_id INT DEFAULT NULL,
    alasan TEXT NOT NULL,
    status ENUM('Menunggu','Diterima','Ditolak') NOT NULL DEFAULT 'Menunggu',
    tanggapan TEXT DEFAULT NULL,
    tanggal_pengajuan TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    tanggal_diproses DATETIME DEFAULT NULL,
    INDEX idx_banding_user (user_id, status),
    INDEX idx_banding_penguji (penguji_id, status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS draft_jawaban (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, form_id INT NOT NULL, payload LONGTEXT NOT NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uniq_draft_user_form (user_id, form_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS aktivitas_asesmen (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id INT NOT NULL, user_id INT DEFAULT NULL, hasil_id INT DEFAULT NULL, pengajuan_id INT DEFAULT NULL, event_type VARCHAR(50) NOT NULL, description VARCHAR(500) NOT NULL, metadata LONGTEXT DEFAULT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_activity_result (hasil_id, created_at), INDEX idx_activity_user (user_id, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS notifikasi (id BIGINT AUTO_INCREMENT PRIMARY KEY, recipient_id INT NOT NULL, type VARCHAR(50) NOT NULL, title VARCHAR(150) NOT NULL, message VARCHAR(500) NOT NULL, target_url VARCHAR(500) DEFAULT NULL, read_at DATETIME DEFAULT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_notification_recipient (recipient_id, read_at, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Bank soal PK1 Eliminasi Urin
USE db_keperawatan;

INSERT INTO bank_soal (jenis_tes, topik, judul, deskripsi, pertanyaan)
VALUES ('PK1', 'Eliminasi Urine', 'Asesmen PK 1 Eliminasi Urin', 'Asesmen unit kompetensi KES.PG02.040.01 Memfasilitasi Pemenuhan Kebutuhan Eliminasi Urin.', CONVERT( USING utf8mb4))
ON DUPLICATE KEY UPDATE
    judul = VALUES(judul),
    deskripsi = VALUES(deskripsi),
    pertanyaan = VALUES(pertanyaan);

UPDATE form_ujian f
JOIN pengajuan p ON p.id = f.pengajuan_id
SET f.judul = 'Asesmen PK 1 Eliminasi Urin',
    f.deskripsi = 'Asesmen unit kompetensi KES.PG02.040.01 Memfasilitasi Pemenuhan Kebutuhan Eliminasi Urin.',
    f.pertanyaan = CONVERT( USING utf8mb4)
WHERE p.jenis_tes = 'PK1' AND p.topik = 'Eliminasi Urine';


